<?php
// Mullion Watch — the auto_prepend_file of watched sites. Generated by
// mullion: do not edit, changes are overwritten.
//
// It is a no-op unless this request belongs to a watched site: Caddy
// passes MULLION_WATCH (that site's events folder) for watched sites
// only, and Mullion sets it in the environment of a watched site's
// workers and commands. php-fpm keeps a PHP_VALUE for the later
// requests its worker serves, so other sites can reach this file too —
// they find no MULLION_WATCH and return at once.
(static function () {
    $dir = $_SERVER['MULLION_WATCH'] ?? getenv('MULLION_WATCH');
    if (!is_string($dir) || $dir === '' || !is_dir($dir)) {
        return;
    }
    if (PHP_SAPI === 'cli' || PHP_SAPI === 'phpdbg') {
        // Only artisan (queue workers, commands) — not composer, not
        // plain scripts, not artisan's own plumbing.
        $argv = $_SERVER['argv'] ?? [];
        if (!isset($argv[0]) || basename((string) $argv[0]) !== 'artisan') {
            return;
        }
        $skip = ['list', '_complete', 'completion', 'help', 'package:discover', 'serve', 'tinker', 'vendor:publish'];
        if (isset($argv[1]) && in_array($argv[1], $skip, true)) {
            return;
        }
    }
    $cfg = @json_decode((string) @file_get_contents($dir . '/config.json'), true);
    if (!is_array($cfg) || empty($cfg['enabled']) || (empty($cfg['dumps']) && empty($cfg['deep']))) {
        return;
    }
    if (class_exists('MullionWatch\\Watcher', false)) {
        return;
    }
    try {
        require __DIR__ . '/mullion-watch-lib.php';
        \MullionWatch\Watcher::start($dir, $cfg);
    } catch (\Throwable $e) {
        // Never break the app.
    }
})();
